from pysat.solvers import Cadical153, Glucose3
from pysat.card import CardEnc, EncType
from pysat.formula import IDPool

def solve(extra_clauses=[]):
    n_cliques=5;k=3;N=15;M=27
    edges=[]
    for g in range(n_cliques):
        for i in range(k):
            for j in range(i+1,k): edges.append((g*k+i,g*k+j))
    for g in range(n_cliques-1):
        for i in range(k): edges.append((g*k+i,(g+1)*k+i))
    vpool=IDPool()
    def x(v,l): return vpool.id(('x',v,l))
    def y(e,d): return vpool.id(('y',e,d))
    clauses=[]
    for v in range(N):
        lits=[x(v,l) for l in range(M+1)]
        clauses.append(lits)
        clauses.extend(CardEnc.atmost(lits, bound=1, vpool=vpool, encoding=EncType.seqcounter).clauses)
    for l in range(M+1):
        lits=[x(v,l) for v in range(N)]
        clauses.extend(CardEnc.atmost(lits, bound=1, vpool=vpool, encoding=EncType.seqcounter).clauses)
    for e in range(M):
        lits=[y(e,d) for d in range(1,M+1)]
        clauses.append(lits)
        clauses.extend(CardEnc.atmost(lits, bound=1, vpool=vpool, encoding=EncType.seqcounter).clauses)
    for d in range(1,M+1):
        lits=[y(e,d) for e in range(M)]
        clauses.extend(CardEnc.atmost(lits, bound=1, vpool=vpool, encoding=EncType.seqcounter).clauses)
    for e,(u,v) in enumerate(edges):
        for a in range(M+1):
            for b in range(M+1):
                if a==b: continue
                clauses.append([-x(u,a), -x(v,b), y(e,abs(a-b))])
    clauses.extend(extra_clauses)
    print('vars', vpool.top, 'clauses', len(clauses))
    with Cadical153(bootstrap_with=clauses) as s:
        sat=s.solve()
        print('sat?',sat)
        if sat:
            model=set(l for l in s.get_model() if l>0)
            sol=[]
            for v in range(N): sol.append(next(l for l in range(M+1) if x(v,l) in model))
            print(sol)
            diffs=[abs(sol[u]-sol[v]) for u,v in edges]
            print(sorted(diffs), len(set(diffs)))
            print([(edges[i],d) for i,d in enumerate(diffs)])
            return sol
    return None
solve()
